      { topic: "Đoạn thẳng, trung điểm", type: "num", q: "Trên tia Ax lấy hai điểm B và C sao cho AB = 4 cm, AC = 9 cm (hình vẽ). Tính độ dài đoạn thẳng BC.", ans: 5, unit: "cm",
        x: "Trên tia Ax có AB < AC (4 cm < 9 cm) nên B nằm giữa A và C. Do đó AB + BC = AC, suy ra BC = 9 − 4 = 5 (cm).", lv: 2,
        svg: '<svg viewBox="0 0 320 110" width="320"><title>Tia Ax có hai điểm B và C, AB = 4 cm, AC = 9 cm</title><line x1="30" y1="70" x2="302" y2="70" stroke-width="2"/><polygon points="312,70 300,64 300,76" fill="ink" stroke="none"/><text x="300" y="56" text-anchor="middle" font-style="italic">x</text><circle cx="30" cy="70" r="4" fill="ink" stroke="none"/><circle cx="130" cy="70" r="4" fill="ink" stroke="none"/><circle cx="255" cy="70" r="4" fill="ink" stroke="none"/><text x="30" y="96" text-anchor="middle" font-weight="700">A</text><text x="130" y="96" text-anchor="middle" font-weight="700">B</text><text x="255" y="96" text-anchor="middle" font-weight="700">C</text></svg>' },
      { topic: "Đoạn thẳng, trung điểm", type: "mc", q: "Cho đoạn thẳng MN = 8 cm. Trên tia MN lấy điểm P sao cho MP = 4 cm, rồi lấy điểm Q sao cho N là trung điểm của đoạn thẳng PQ. Độ dài đoạn thẳng MQ là:", o: ["12 cm", "8 cm", "4 cm", "16 cm"],
        x: "Trên tia MN có MP < MN (4 cm < 8 cm) nên P nằm giữa M và N: PN = MN − MP = 4 (cm). N là trung điểm của PQ nên N nằm giữa P, Q và NQ = PN = 4 cm. Khi đó N nằm giữa M và Q: MQ = MN + NQ = 8 + 4 = 12 (cm).", lv: 3 }
